def is_independent_set(subset, N):
    # Check constraints: difference must not be 1 or 21
    for i in range(len(subset)):
        for j in range(i + 1, len(subset)):
            x = subset[i]
            y = subset[j]
            diff = abs(x - y)
            if diff == 1 or diff == 21:
                return False
    return True

# Test case N=10. Since max diff is 9, only diff=1 matters.
N_small = 10
vertices = list(range(1, N_small + 1))
count = 0

# Iterate through all 2^N subsets
for i in range(2**N_small):
    subset = []
    for j in range(N_small):
        if (i >> j) & 1:
            subset.append(vertices[j])

    if is_independent_set(subset, N_small):
        count += 1

print(f"Number of independent sets for N={N_small} is: {count}")

